import { DynamicModule, Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';

import appConfig from './config/app.config';
import authConfig from './config/auth.config';
import bullmqConfig from './config/bullmq.config';
import databaseConfig from './config/database.config';
import observabilityConfig from './config/observability.config';
import realtimeConfig from './config/realtime.config';
import redisConfig from './config/redis.config';
import s3Config from './config/s3.config';
import securityConfig from './config/security.config';
import { validateEnv } from './schemas/env.schema';

const ALL_CONFIGS = [
  appConfig,
  databaseConfig,
  redisConfig,
  bullmqConfig,
  s3Config,
  authConfig,
  realtimeConfig,
  observabilityConfig,
  securityConfig,
];

export interface ConfigurationModuleOptions {
  /** Extra .env files to load, in addition to the process environment. Mainly useful for tests. */
  envFilePath?: string | string[];
}

/**
 * Single source of typed, validated configuration for api/worker/realtime/scheduler/cli.
 * Every environment variable is read and validated here; business modules must not read
 * process.env directly (enforced by the architecture test).
 */
@Module({})
export class ConfigurationModule {
  static register(options: ConfigurationModuleOptions = {}): DynamicModule {
    return {
      module: ConfigurationModule,
      imports: [
        ConfigModule.forRoot({
          isGlobal: true,
          cache: true,
          envFilePath: options.envFilePath ?? '.env',
          load: ALL_CONFIGS,
          validate: validateEnv,
        }),
      ],
      exports: [ConfigModule],
    };
  }

  /**
   * `@nestjs/config`'s ConfigModule only exposes `forRoot` (no `forRootAsync`), so the async
   * variant here just resolves the options factory before building the same `forRoot` call —
   * `imports` accepts a `Promise<DynamicModule>` directly, so this stays lazy either way.
   */
  static registerAsync(
    optionsFactory: () => Promise<ConfigurationModuleOptions> | ConfigurationModuleOptions,
  ): DynamicModule {
    const configModule = Promise.resolve(optionsFactory()).then((options) =>
      ConfigModule.forRoot({
        isGlobal: true,
        cache: true,
        envFilePath: options.envFilePath ?? '.env',
        load: ALL_CONFIGS,
        validate: validateEnv,
      }),
    );

    return {
      module: ConfigurationModule,
      imports: [configModule],
      exports: [ConfigModule],
    };
  }
}

