    { provide: ACCOUNT_PHONE_SEARCH, useClass: AccountPhoneSearchService },
    { provide: ID_GENERATOR, useClass: UuidGenerator },
    { provide: CLOCK, useClass: SystemClock },
    LocalAuthenticationProvider,
