function toAccountResponseDto(detail: AccountDetail | AccountSummary): AccountResponseDto {
  return {
    id: detail.id,
    status: detail.status,
    phone: detail.phone,
    createdAt: detail.createdAt,
    updatedAt: detail.updatedAt,
  };
}

/**
 * §16. Never returns the ORM entity, never exposes `passwordHash` (AC #25/#34). Account management
 * is an admin-portal operation — `@RequirePortal('ADMIN')` rejects a token issued for the PUBLIC
 * portal even if the same Account also holds `account.*` permissions (AC #23, task.md §13
 * "Token phát cho PUBLIC không được tự động sử dụng để truy cập ADMIN nếu audience/portal không
 * hợp lệ"). Must run after `JwtAuthGuard` (needs `request.user.portal`) and before
 * `PermissionsGuard`.
 */
@ApiTags('accounts')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, PortalGuard, PermissionsGuard)
@RequirePortal('ADMIN')
@Controller('accounts')
export class AccountController {
  constructor(
    private readonly createAccount: CreateAccountUseCase,
    private readonly getAccount: GetAccountUseCase,
    private readonly listAccounts: ListAccountsUseCase,
    private readonly updateAccount: UpdateAccountUseCase,
    private readonly changeAccountStatus: ChangeAccountStatusUseCase,
    private readonly changeAccountPhone: ChangeAccountPhoneUseCase,
    private readonly changeAccountPassword: ChangeAccountPasswordUseCase,
    private readonly deleteAccount: DeleteAccountUseCase,
  ) {}

  @Post()
  @RequirePermissions('account.create')
  @ApiResponse({ status: HttpStatus.CREATED, type: CreateAccountResponseDto })
  async create(
    @CurrentUser() user: RequestUser,
    @Body() dto: CreateAccountDto,
  ): Promise<CreateAccountResponseDto> {
    return this.createAccount.execute({
      phone: dto.phone,
      password: dto.password,
      fullName: dto.fullName,
      email: dto.email,
      dateOfBirth: dto.dateOfBirth ? new Date(dto.dateOfBirth) : undefined,
      address: dto.address,
      avatarId: dto.avatarId,
      actorId: user.id,
    });
  }

  @Get()
  @RequirePermissions('account.read')
  @ApiResponse({ status: HttpStatus.OK, type: ListAccountsResponseDto })
  async list(@Query() query: ListAccountsQueryDto): Promise<ListAccountsResponseDto> {
    const result = await this.listAccounts.execute({
      status: query.status,
      provider: query.provider,
      phoneSearch: query.phone,
      page: query.page,
      pageSize: query.pageSize,
      sortBy: query.sortBy,
      sortDirection: query.sortDirection,
    });
    return {
      items: result.items.map(toAccountResponseDto),
      total: result.total,
      page: result.page,
      pageSize: result.pageSize,
      totalPages: result.totalPages,
    };
  }

  @Get(':accountId')
  @RequirePermissions('account.read')
  @ApiParam({ name: 'accountId', type: String, format: 'uuid' })
  @ApiResponse({ status: HttpStatus.OK, type: AccountResponseDto })
  async getById(@Param('accountId') accountId: string): Promise<AccountResponseDto> {
    const detail = await this.getAccount.execute({ accountId });
    return toAccountResponseDto(detail);
  }

  @Patch(':accountId')
  @RequirePermissions('account.update')
  @ApiParam({ name: 'accountId', type: String, format: 'uuid' })
  @ApiResponse({ status: HttpStatus.OK, type: AccountResponseDto })
  async update(@Param('accountId') accountId: string): Promise<AccountResponseDto> {
    const detail = await this.updateAccount.execute({ accountId });
    return toAccountResponseDto(detail);
  }

  @Patch(':accountId/status')
  @RequirePermissions('account.change-status')
  @ApiParam({ name: 'accountId', type: String, format: 'uuid' })
  @ApiResponse({ status: HttpStatus.NO_CONTENT })
  @HttpCode(HttpStatus.NO_CONTENT)
  async changeStatus(
    @CurrentUser() user: RequestUser,
    @Param('accountId') accountId: string,
    @Body() dto: ChangeAccountStatusDto,
  ): Promise<void> {
    await this.changeAccountStatus.execute({ accountId, status: dto.status, actorId: user.id });
  }

  @Patch(':accountId/phone')
  @RequirePermissions('account.update')
  @ApiParam({ name: 'accountId', type: String, format: 'uuid' })
  @ApiResponse({ status: HttpStatus.NO_CONTENT })
  @HttpCode(HttpStatus.NO_CONTENT)
  async changePhone(
    @CurrentUser() user: RequestUser,
    @Param('accountId') accountId: string,
    @Body() dto: ChangeAccountPhoneDto,
  ): Promise<void> {
    await this.changeAccountPhone.execute({ accountId, newPhone: dto.phone, actorId: user.id });
  }

  @Patch(':accountId/password')
  @RequirePermissions('account.change-password')
  @ApiParam({ name: 'accountId', type: String, format: 'uuid' })
  @ApiResponse({ status: HttpStatus.NO_CONTENT })
  @HttpCode(HttpStatus.NO_CONTENT)
  async changePassword(
    @CurrentUser() user: RequestUser,
    @Param('accountId') accountId: string,
    @Body() dto: ChangeAccountPasswordDto,
  ): Promise<void> {
    await this.changeAccountPassword.execute({
      accountId,
      newPassword: dto.newPassword,
      actorId: user.id,
    });
  }

  @Delete(':accountId')
  @RequirePermissions('account.delete')
  @ApiParam({ name: 'accountId', type: String, format: 'uuid' })
  @ApiResponse({ status: HttpStatus.NO_CONTENT })
  @HttpCode(HttpStatus.NO_CONTENT)
  async remove(
    @CurrentUser() user: RequestUser,
    @Param('accountId') accountId: string,
  ): Promise<void> {
    await this.deleteAccount.execute({ accountId, actorId: user.id });
  }
}

