import { Inject, Injectable, UnauthorizedException } from '@nestjs/common';

import {
  AuthenticationCredential,
  AuthenticationProvider,
  AuthenticationResult,
} from '../../application/ports/authentication-provider.port';
import { PASSWORD_HASHER, PasswordHasher } from '../../application/ports/password-hasher.port';
import {
  AUTH_IDENTITY_REPOSITORY,
  AuthIdentityRepository,
} from '../../domain/auth-identities/auth-identity.repository';
import { AuthProvider } from '../../domain/auth-identities/auth-provider';

interface LocalCredential extends AuthenticationCredential {
  provider: AuthProvider.Local;
  identifier: string;
  plainPassword: string;
}

/**
 * §11 LOCAL provider: verifies a normalized phone + password against the matching LOCAL
 * `AuthIdentity`. Always throws the same generic `UnauthorizedException` whether the phone is
 * unknown or the password is wrong (api-contract.md — no account enumeration, task.md §9).
 */
@Injectable()
export class LocalAuthenticationProvider implements AuthenticationProvider {
  readonly provider = AuthProvider.Local;

  constructor(
    @Inject(AUTH_IDENTITY_REPOSITORY) private readonly authIdentities: AuthIdentityRepository,
    @Inject(PASSWORD_HASHER) private readonly passwordHasher: PasswordHasher,
  ) {}

  async authenticate(credential: AuthenticationCredential): Promise<AuthenticationResult> {
    const { identifier, plainPassword } = credential as LocalCredential;

    const identity = await this.authIdentities.findByProviderAndIdentifier(AuthProvider.Local, identifier);
    if (!identity || !identity.passwordHash) {
      throw new UnauthorizedException('Invalid phone or password');
    }

    const passwordMatches = await this.passwordHasher.verify(plainPassword, identity.passwordHash);
    if (!passwordMatches) {
      throw new UnauthorizedException('Invalid phone or password');
    }

    return { accountId: identity.accountId, authIdentityId: identity.id.toValue() };
  }
}

