  /**
   * LOCAL AuthIdentity stores phone in E.164 (`+849...`), but an admin naturally searches using
   * the same local format accepted everywhere else (login, create-account — e.g. `0912345678`),
   * which never appears as a substring of the stored value (§9/§19 "Chuẩn hóa phone trước khi
   * query"). A full, parseable phone search term is normalized to E.164 before the repository's
   * `ILIKE` match; a partial term (e.g. `5678`) can't be parsed as a phone number at all, so it is
   * passed through unchanged to keep substring search working.
   */
  private normalizePhoneSearch(phoneSearch: string | undefined): string | undefined {
    if (!phoneSearch) {
      return phoneSearch;
    }
    try {
      const auth = this.configService.getOrThrow<AuthConfig>('auth');
      return this.phoneNormalizer.normalize(phoneSearch, auth.phone.defaultRegion).value;
    } catch {
      return phoneSearch;
    }
  }
}

